template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}
.label {
  box-sizing: border-box;
  width: 50mm;
  height: 30mm;
  padding: 1.6mm 1.8mm 1.2mm;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.name {
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.15;
  max-height: 2.3em;
  overflow: hidden;
}
.price {
  font-size: 16px;
  font-weight: 800;
  margin-top: 0.6mm;
  line-height: 1;
  letter-spacing: -0.02em;
}
.currency {
  font-size: 9px;
  font-weight: 700;
  margin-left: 0.8mm;
}
.meta {
  font-size: 7px;
  font-weight: 500;
  margin-top: 0.5mm;
  color: #444;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.barcode-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35mm;
  margin-top: auto;
  width: 100%;
}
.code {
  font-size: 7.5px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.05em;
  text-align: center;
  white-space: nowrap;
}
img.barcode {
  height: 10mm;
  width: 100%;
  max-width: 100%;
  object-fit: contain;
  object-position: center bottom;
}
